Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.
Ltac accok_fp_on ::= fail.

(* [comment removed for export] *)
Ltac reg_get_set_lit :=
  unfold reg_get;
  repeat (lazymatch goal with
    | |- context [bvmap_get ?k (bvmap_set ?k' ?a ?M)] =>
        first [ replace (bvmap_get k (bvmap_set k' a M)) with (Some a)
                  by (symmetry; replace k with k' by (apply bv_eq; vm_compute; reflexivity); apply bvmap_get_set_same)
              | replace (bvmap_get k (bvmap_set k' a M)) with (bvmap_get k M)
                  by (symmetry; apply bvmap_get_set_other; let E := fresh in intros E; apply (f_equal bv_unsigned) in E; vm_compute in E; discriminate E) ]
    end);
  cbv iota beta; apply bv_eq; vm_compute; reflexivity.

(* [comment removed for export] *)
Ltac lres_tac2 :=
  unfold lres; repeat match goal with H : rt_frames _ _ = _ |- _ => rewrite H end;
  repeat match goal with H : rt_live _ _ = _ |- _ => rewrite H end;
  unfold pix_new_live, RASTER_COST, RC1 in *; cbn [length app]; unfold FRAMES_MAX, LIVE_MAX in *;
  split; [lia|]; split; [lia|]; split; [lia|];
  let p := fresh "p" in let n := fresh "n" in let Hn := fresh "Hn" in intros p n Hn; cbn [In] in Hn;
  repeat (destruct Hn as [Hn|Hn]; [injection Hn as <- <-; first [clear; lia | unfold rsize; lia] |]);
  lazymatch goal with L : forall q k, In (q, k) _ -> 0 < k |- _ => exact (L _ _ Hn) end.

(* [comment removed for export] *)
Ltac fs_agree_tac2 :=
  first
    [ apply fs_agree_refl
    | assumption
    | let r := fresh "r" in let Hr := fresh "Hr" in
      intros r Hr; apply fs_callee_cases in Hr; cbn [map In] in Hr;
      repeat (destruct Hr as [<-|Hr]); [..| destruct Hr];
      repeat (rewrite ?fs_reg_get_set; fs_eqb_simp;
              first [ reflexivity
                    | match goal with H : fs_agree ?F1 ?F2 |- context [reg_get ?F2 ?rr] => rewrite (fs_agree_get F1 F2 rr H) by reflexivity end ]);
      reflexivity ].

Definition rb2_bm : Z := e_pixReduceRankBinary2 + 0x308.    (* [comment removed for export] *)

Definition RB2_STOPS : list Z := [e_stack_malloc 1%nat; e_returnErrorPtr; e_pixSetPadBits; e_pixCreate; e_pixCopyResolution_po; e_pixScaleResolution; rb2_rh; rb2_fl].

Section RB2C.
Variable RT : rt_sig.
Hypothesis AF : art_facts RT.
Hypothesis GP : rt_gaps RT.
Hypothesis FKC : rt_fk_contracts RT.
Hypothesis PAD : pixSetPadBits_cpsF RT.
Hypothesis CRE : pixCreate_res0_cpsF RT.
Hypothesis CRE1 : pixCreate1_sure_cps RT.
Hypothesis CPR : pixCopyResolution_po_cps RT.
Hypothesis SCR : pixScaleResolution_cps RT.
Hypothesis RERR : returnError_cpsF RT e_returnErrorPtr.
Hypothesis LIT1 : exists l, In (A_MSG_RB2_NULL, l) LEPT_LITS.
Hypothesis LIT2 : exists l, In (A_MSG_RB2_HS, l) LEPT_LITS.
Hypothesis LIT3 : exists l, In (A_MSG_RB2_PIXD, l) LEPT_LITS.
Hypothesis LIT4 : exists l, In (A_PROC_RB2, l) LEPT_LITS.

